-- Door 1
VALUES (1, 1, 'Brann', 'Hvor lang tid etter oppstart av helse- og omsorgstjenester i hjemmet skal brannrisikovurderingen senest være gjennomført?', 'Brannrisikovurdering skal gjøres senest to uker etter oppstart, og deretter minimum én gang i året.', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 2
VALUES (1, 2, 'Brann', 'Hva er minstekravet til brannsikkerhetsutstyr i alle hjem?', 'Alle hjem skal ha fungerende brannslukningsutstyr (slukkeapparat eller brannslange) og minimum én røykvarsler i hver etasje.', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 3
VALUES (1, 3, 'Brann', 'Hvordan skal røykvarsleren være plassert?', 'Røykvarsleren skal sitte i taket, minst 50 cm fra veggen. Innbygger skal også kunne høre den bak lukket soveromsdør.', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 4
VALUES (1, 4, 'Brann', 'Hvilket tiltak skal opprettes i Gerica med årlig tidsplan for brannrisikovurdering?', 'Alle oppretter tiltaket «x.13.1.2 Brannskjema – fylle ut» med årlig tidsplan i innbyggers tiltaksplan.', 'Gerica – Brannsjekk i Gerica', '49676');
SET @q = LAST_INSERT_ID();

-- Door 5
VALUES (1, 5, 'Brann', 'Innbygger takker nei til brannrisikovurdering. Hvilket brannrisikonivå får innbygger i ELISE?', 'Velg «Innbygger ønsker ikke kartlegging», skriv obligatorisk begrunnelse og fyll inn dato. Innbygger får nivå «Ikke vurdert».', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 6
VALUES (1, 6, 'Brann', 'Hvilket tiltaksnivå i ELISE inkluderer mobilt vanntåkeanlegg?', 'Tiltaksnivå 3 har alt fra nivå 2 og i tillegg mobilt vanntåkeanlegg.', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 7
VALUES (1, 7, 'Brann', 'Hvordan sjekker du at et pulverapparat fungerer?', 'Pulverapparat snus opp ned mens du lytter etter pulveret. Pilen skal stå på grønt, og sikring og splint skal være på plass.', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 8
VALUES (1, 8, 'Brann', 'Hvor skal bydelen i hovedsak bestille komfyrvakt?', 'Komfyrvakt bestilles hovedsakelig gjennom NAV Hjelpemiddelsentral. Ved avslag kan du sende forespørsel til BRE servicesenteret.', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 9
VALUES (1, 9, 'Brann', 'Du er bekymret for brannsikkerheten hjemme hos en innbygger. Hva gjør du først?', 'Vurder saken med leder og les om bekymringsmelding og taushetsplikt på branntips.no. Meldingen registreres der og går videre til lokalt brannvesen.', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 10
VALUES (1, 10, 'Brann', 'Hvilken frekvens setter du i tidsplanen i Gerica når brannsjekken skal komme på arbeidslisten én gang i året?', 'Frekvensen er i uker. Frekvens 52 betyr hver 52. uke, altså én gang i året.', 'Gerica – Brannsjekk i Gerica', '49676');
SET @q = LAST_INSERT_ID();

-- Door 11
VALUES (1, 11, 'Brann', 'Hvilken av disse hendelsene skal utløse en ny brannrisikovurdering før det har gått et år?', 'Ny vurdering gjøres ved endringer i ADL, medisiner eller funksjonsnivå, og når innbygger blir aleneboende.', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 12
VALUES (1, 12, 'Brann', 'Hvem passer flammehemmende sengetøy for?', 'Flammehemmende sengetøy reduserer risikoen hvis innbygger som røyker sovner eller mister sigaretten. Det skaffes av innbygger, pårørende eller bydelen.', 'ELISE/Gerica – Brannrisikovurdering – tjenester i hjemmet', '38729');
SET @q = LAST_INSERT_ID();

-- Door 13
VALUES (1, 13, 'Ernæring', 'Hvilke to verktøy brukes for å vurdere risiko for underernæring?', 'MST (Malnutrition Screening Tool) og kroppsmasseindeks (KMI, BMI i Gerica) brukes ved vurdering av risiko for underernæring.', 'Gerica – Ernæring – Forebygging og behandling av underernæring', '39407');
SET @q = LAST_INSERT_ID();

-- Door 14
VALUES (1, 14, 'Ernæring', 'Hvilken MST-skår betyr at bruker er i risiko for underernæring?', 'En total poengskår på 2 eller mer betyr risiko for underernæring og behov for individuell kartlegging.', 'Gerica – Ernæring – Forebygging og behandling av underernæring', '39407');
SET @q = LAST_INSERT_ID();

-- Door 15
VALUES (1, 15, 'Ernæring', 'Under hvilken KMI regnes en person over 70 år som undervektig?', 'Over 70 år: under 22 er undervekt og 22–27 er normalvekt. Under 70 år går grensen ved 18,5.', 'Gerica – Ernæring – Forebygging og behandling av underernæring', '39407');
SET @q = LAST_INSERT_ID();

-- Door 16
VALUES (1, 16, 'Ernæring', 'Bruker med hjemmesykepleie skårer under 2 og har KMI over grenseverdiene. Når skal ny risikovurdering gjøres?', 'Ved hjemmesykepleie minimum hver 3. måned. Ved andre helsetjenester og praktisk bistand innen matomsorg minimum hver 6. måned.', 'Gerica – Ernæring – Forebygging og behandling av underernæring', '39407');
SET @q = LAST_INSERT_ID();

-- Door 17
VALUES (1, 17, 'Ernæring', 'Hvilken journaltype brukes for å dokumentere resultatet av risikovurderingen?', 'Resultatet dokumenteres i 170-kartleggingsjournal knyttet til tiltaket «x.13.2.6 Vurdere ernæringsstatus».', 'Gerica – Ernæring – Forebygging og behandling av underernæring', '39407');
SET @q = LAST_INSERT_ID();

-- Door 18
VALUES (1, 18, 'Ernæring', 'Hvor ofte skal brukere i risiko for underernæring eller som er underernærte veies?', 'Tiltaket «x.3.9.6 Vektkontroll» legges inn med fast tidsplan, minimum ukentlig eller etter annet faglig begrunnet opplegg.', 'Gerica – Ernæring – Forebygging og behandling av underernæring', '39407');
SET @q = LAST_INSERT_ID();

-- Door 19
VALUES (1, 19, 'Ernæring', 'Hvem skal gjennomføre individuell kartlegging ved risiko for underernæring, og innen når?', 'Tiltaket «x.13.2.10 Individuell kartlegging ernæring» opprettes, og kartleggingen utføres av TA eller PK innen to uker.', 'Gerica – Ernæring – Forebygging og behandling av underernæring', '39407');
SET @q = LAST_INSERT_ID();

-- Door 20
VALUES (1, 20, 'Ernæring', 'Hvor ofte skal ernæringsplanen minimum evalueres ved hjemmesykepleie?', 'TA følger opp sammen med PK minimum månedlig ved hjemmesykepleie, og ved endringer i brukers situasjon. Evalueringen føres i 136 OL-fagjournal.', 'Gerica – Ernæring – Forebygging og behandling av underernæring', '39407');
SET @q = LAST_INSERT_ID();

-- Door 21
VALUES (1, 21, 'Kognisjon', 'Ved hvilken alder anbefales første «Tidlig tegn»-kartlegging for personer med Downs syndrom?', 'For alle brukere lages en baseline ved fylte 40 år. For personer med Downs syndrom anbefales første kartlegging ved fylte 30, sammen med Adaptiv Demensscreening.', 'Kartlegging av tidlige tegn på kognitiv svikt hos personer med utviklingshemming', '65800');
SET @q = LAST_INSERT_ID();

-- Door 22
VALUES (1, 22, 'Kognisjon', 'Hvem skal gjennomføre «Tidlig tegn»-kartleggingen?', 'Kartleggingen gjøres sammen med bruker og to ansatte, helst med en ansatt som kjenner bruker godt. Pårørende kan involveres ved behov.', 'Kartlegging av tidlige tegn på kognitiv svikt hos personer med utviklingshemming', '65800');
SET @q = LAST_INSERT_ID();

-- Door 23
VALUES (1, 23, 'Kognisjon', 'Hvilken diagnosekode registreres i Gerica for å angi demens?', 'P70 angir demens. P85 psykisk utviklingshemning registreres i tillegg der det er relevant.', 'Kartlegging av tidlige tegn på kognitiv svikt hos personer med utviklingshemming', '65800');
SET @q = LAST_INSERT_ID();

-- Door 24
VALUES (1, 24, 'Demens', 'Demenskoordinator og fastlege kommuniserer vanligvis med dialogmelding. Hva gjør du hvis noe haster?', 'Om noe haster, ring. Fastlegen bør ha telefonnummeret til demenskoordinator, og demenskoordinator bør vite hvordan fastlegen nås.', 'Samhandling mellom demenskoordinator/hukommelsesteam og fastleger', '65365');
SET @q = LAST_INSERT_ID();
